const original = {
  user: { name: 'Ada', tags: ['admin'] },
  meta: { createdAt: new Date() },
};

// Shallow copy: new top object, SHARED user/tags
const shallow = { ...original };
shallow.user.name = 'Lin';           // ⚠️ original.user.name is now 'Lin' too
shallow.meta = { ...shallow.meta };  // fix level by level when needed

// Correct immutable update: spread every level you change
const updated = {
  ...original,
  user: { ...original.user, name: 'Lin' },   // tags still shared — fine, unchanged
};
// original.user.name stays 'Ada' — structural sharing: untouched subtrees stay shared

// Deep copy: nothing shared
const deep = structuredClone(original);
deep.user.name = 'Grace';            // original untouched
deep.meta.createdAt;                 // real Date, independent

// JSON round-trip: the lossy version
JSON.parse(JSON.stringify(original)).meta.createdAt;  // STRING, not Date
// functions dropped, undefined vanishes, cycles throw TypeError

// structuredClone limitations:
// structuredClone({ fn: () => {} });      // DataCloneError
// structuredClone(new HTMLElement());     // DataCloneError
// structuredClone(new MyClass());         // loses prototype -> plain object

// React flavor: forgetting the nested level is the classic immutability bug
function renameBad(state, name) {
  return { ...state, user: { name } };          // ⚠️ dropped other user fields? no — replaced entire user
}
function renameGood(state, name) {
  return { ...state, user: { ...state.user, name } };  // ✅
}
